'use strict';
const $=s=>document.querySelector(s);
let current='home',activeFilter='all',animated=false,playing=false,timer,state=null,roomPage=0,friendPage=0,dmPeer='',newsPage=0,newsVersion=0,lastRoom=null,lastDuelResult=null,memberPage=0;
window.btcRenderErrors=[];window.addEventListener('error',e=>window.btcRenderErrors.push(e.message));
const signatures={};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function changed(key,value){const next=JSON.stringify(value);if(signatures[key]===next)return false;signatures[key]=next;return true;}
async function api(kind,values={}){try{const result=await window.pywebview.api.command(kind,values);if(!result.ok){toast(result.error);return null;}return result;}catch(e){toast('No se pudo completar la operación.');return null;}}
function toast(s){clearTimeout(timer);$('#toast').textContent=s;$('#toast').hidden=false;timer=setTimeout(()=>$('#toast').hidden=true,6000);}
function dialog(html){$('#dialog').classList.remove('setup-dialog','profile-dialog','profile-authorizing');$('#dialog-content').innerHTML=html;$('#dialog').showModal();$('#profile-menu').hidden=true;}
function closeDialog(){$('#dialog').close();}

// A separate top-layer dialog keeps the current form intact underneath it.
const duelAlert=document.createElement('dialog');
duelAlert.id='duel-alert';duelAlert.setAttribute('aria-labelledby','duel-alert-title');
document.body.append(duelAlert);
duelAlert.addEventListener('cancel',e=>e.preventDefault());
const duelAlerts=createDuelAlertController({
    show(offer,respond){
        duelAlert.innerHTML=`<span class="eyebrow">TE HAN DESAFIADO</span><h2 id="duel-alert-title">${esc(offer.name||'Un jugador')} quiere pelear.</h2><p>Acepta el duelo para abrir el juego.</p><div class="duel-offer-rules"><span>FT${esc(offer.ft)}</span><span>${esc(offer.seconds)} segundos</span><span>${esc(offer.characters)} personajes</span></div><p class="duel-offer-note">Elige tus personajes dentro del juego.</p><footer><button class="secondary" id="duel-alert-decline">Rechazar</button><button class="primary" id="duel-alert-accept">ACEPTAR DUELO ↗</button></footer>`;
        $('#duel-alert-decline').onclick=()=>respond(false);
        $('#duel-alert-accept').onclick=()=>respond(true);
        if(!duelAlert.open)duelAlert.showModal();
        $('#duel-alert-decline').focus();
    },
    hide(){duelAlert.close();},
    pending(value){duelAlert.querySelectorAll('button').forEach(b=>b.disabled=value);},
    async reply(offer,accept){
        const result=offer.kind==='social'
            ?await api('social',{op:accept?'accept':'decline',event:offer.id})
            :await api(accept?'accept_duel':'decline_duel');
        if(result)toast(accept?'Duelo aceptado. Preparando el juego…':'Desafío rechazado.');
        return !!result;
    }
});

function footer(primary='Aceptar'){return '<footer><button class="secondary" type="button" onclick="closeDialog()">Cancelar</button><button class="primary" type="submit">'+esc(primary)+'</button></footer>';}
function screen(id,html){const el=document.createElement('section');el.id=id;el.className='view';el.innerHTML=html;$('main').append(el);}
function showView(id){current=id;document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===(['lobby','duel'].includes(id)?'rooms':id)));$('#profile-menu').hidden=true;if(id==='rooms'){api('rooms');renderRooms();}if(id==='duel'){if(innerWidth<=1000){$('#social').hidden=true;$('#social-toggle').setAttribute('aria-expanded','false');}renderCombat();}}
function openFriends(){$('#social').hidden=false;$('#social-toggle').setAttribute('aria-expanded','true');}
function socialToggle(){const open=$('#social').hidden;$('#social').hidden=!open;$('#social-toggle').setAttribute('aria-expanded',String(open));}
$('#social-toggle').onclick=socialToggle;$('#close-social').onclick=socialToggle;
if(innerWidth<=900){$('#social').hidden=true;$('#social-toggle').setAttribute('aria-expanded','false');}
$('#profile-toggle').onclick=()=>$('#profile-menu').hidden=!$('#profile-menu').hidden;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;roomPage=0;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderRooms();});
$('#room-search').oninput=()=>{roomPage=0;renderRooms();};
$('#room-list').replaceChildren();
$('#social').querySelectorAll('.friend').forEach(e=>e.remove());
const headings=$('#social').querySelectorAll('.social-heading');headings[0].querySelector('span').id='friends-count';headings[1].remove();
const friends=document.createElement('div');friends.className='social-friends';friends.id='friends-list';$('#social').insertBefore(friends,$('.social-hint'));
$('.social-hint').innerHTML='Clic para abrir el chat · clic derecho para más opciones.<br><span id="inbox-summary" role="status" aria-live="polite"></span><br><button onclick="copyFriendCode()" id="friend-code">Mi código de amigo</button>';
let roster=[];
function renderRooms(){const q=$('#room-search').value.toLocaleLowerCase('es');roster=(state?.rooms||[]).filter(r=>(activeFilter==='all'||r.locked===(activeFilter==='private'))&&(r.title+' '+r.host).toLocaleLowerCase('es').includes(q));const size=innerHeight<760?3:5;const max=Math.max(0,Math.ceil(roster.length/size)-1);roomPage=Math.min(roomPage,max);$('#room-list').replaceChildren();for(const r of roster.slice(roomPage*size,(roomPage+1)*size)){const row=document.createElement('div');row.className='room-row';row.innerHTML=`<span class="room-name">${esc(r.title)}<small>${r.locked?'◈ Con contraseña':'Abierta'} · ${esc(r.host)}</small></span><span class="value rules">Acordadas en duelo</span><span class="value region">BTC</span><span class="value slots">${r.count} / ${r.capacity}</span>`;const join=document.createElement('button');join.className='join';join.textContent='ENTRAR ↗';join.disabled=r.count>=r.capacity;join.onclick=()=>joinRoom(r);row.append(join);$('#room-list').append(row);}if(!roster.length)$('#room-list').innerHTML='<p class="empty">No hay salas que coincidan. Puedes crear una o actualizar la lista.</p>';$('#room-count').textContent=roster.length+' salas';const pager=$('.pagination>span:last-child');pager.replaceChildren();for(const [title,delta] of [['←',-1],['→',1]]){const b=document.createElement('button');b.textContent=title;b.disabled=delta<0?roomPage===0:roomPage>=max;b.onclick=()=>{roomPage+=delta;renderRooms();};pager.append(b);}const refresh=document.createElement('button');refresh.textContent='Actualizar';refresh.onclick=()=>api('rooms');pager.append(refresh);}
function createRoom(){if(state?.room){showView('lobby');toast('Sal de tu sala actual antes de crear otra.');return;}dialog('<h2>Tu sala, tus reglas.</h2><p>Reúne a tus amigos para conversar y desafiarse.</p><form id="room-form"><label>Nombre de la sala<input name="title" required maxlength="40" placeholder="Práctica BTC"></label><label>Plazas<select name="capacity"><option>2</option><option>4</option><option selected>8</option><option>16</option><option>32</option></select></label><label>Acceso<select name="access"><option value="public">Público</option><option value="private">Con contraseña</option></select></label><label id="password-label" hidden>Contraseña<input type="password" name="password" maxlength="64"></label>'+footer('CREAR SALA')+'</form>');$('#room-form [name="access"]').onchange=e=>{$('#password-label').hidden=e.target.value!=='private';$('#room-form [name="password"]').required=e.target.value==='private';};$('#room-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await api('create',{title:f.get('title'),capacity:Number(f.get('capacity')),password:f.get('access')==='private'?f.get('password'):''})){closeDialog();toast('Creando la sala…');}};}
function joinRoom(r){if(state?.room){showView('lobby');toast('Ya estás en una sala.');return;}if(r.locked){dialog('<h2>'+esc(r.title)+'</h2><p>Esta sala tiene contraseña.</p><form id="join-form"><label>Contraseña<input type="password" name="password" required></label>'+footer('ENTRAR')+'</form>');$('#join-form').onsubmit=async e=>{e.preventDefault();if(await api('join',{code:r.room_code,password:e.target.password.value}))closeDialog();};}else api('join',{code:r.room_code});}
screen('lobby','<span class="eyebrow">SALA BTC</span><div class="view-heading"><div><button class="back" onclick="leaveRoom()">← Salir de la sala</button><h1 id="lobby-name">Tu sala</h1></div><button class="secondary" onclick="inviteFromList()">Invitar amigo</button></div><div class="room-view-tabs"><button class="chip active" data-pane="players">Jugadores y duelos</button><button class="chip" data-pane="chat">Chat de sala</button></div><div class="room-layout" id="lobby-layout"><div class="room-side" data-room-pane="players"><div class="section-line"><span id="member-count">JUGADORES</span><button class="text-action" onclick="showView(\'duel\')">Ver combate ↗</button></div><div id="members"></div><div class="duel-invite" id="incoming-duel" hidden></div><div class="room-footer"><button class="secondary" onclick="api(\'ready\')" id="ready-button">Marcarme listo</button><small>Los personajes se seleccionan dentro del juego.</small></div></div><div class="room-side chat-panel" data-room-pane="chat"><div class="section-line"><span>CHAT DE SALA</span></div><div class="chat-stream" id="lobby-chat" aria-live="polite"></div><form class="chat-compose" id="lobby-compose"><input maxlength="300" placeholder="Escribe a la sala…" aria-label="Mensaje a la sala" required><button>ENVIAR ↗</button></form></div></div>');
document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>{$('#lobby-layout').classList.toggle('chat-selected',b.dataset.pane==='chat');document.querySelectorAll('[data-pane]').forEach(x=>x.classList.toggle('active',x===b));});
$('#lobby-compose').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input');if(await api('chat',{text:input.value}))input.value='';};
async function leaveRoom(){if(state?.ranked?.match&&!state.ranked.match.finished){rankedForfeit();return;}if(await api('leave'))showView('rooms');}
function chatMessage(stream,name,text,kind=''){const el=document.createElement('div');el.className='chat-message '+kind;const author=document.createElement('strong');author.textContent=name;const p=document.createElement('p');p.textContent=text;el.append(author,p);stream.append(el);}
function renderLobby(){const r=state.room;if(!r)return;$('#lobby-name').textContent=r.title;$('#member-count').textContent='JUGADORES / '+r.users.length+' DE '+r.capacity;const me=r.users.find(u=>u.id===r.self_id);$('#ready-button').textContent=me?.ready?'Volver a disponible':'Marcarme listo';if(changed('members',[r.users,r.self_id,r.host_id,memberPage,innerHeight,!!r.duel])){$('#members').replaceChildren();const pageSize=innerHeight<760?(r.duel?2:3):(r.duel?4:5);memberPage=Math.min(memberPage,Math.max(0,Math.ceil(r.users.length/pageSize)-1));for(const u of r.users.slice(memberPage*pageSize,(memberPage+1)*pageSize)){const el=document.createElement('div');el.className='member';el.innerHTML=`<span class="avatar">${esc(u.name[0])}</span><span class="member-name">${esc(u.name)}${u.id===r.self_id?' · TÚ':''}<small>${u.id===r.host_id?'Anfitrión · ':''}${u.ready?'Listo':'Disponible'}</small></span>`;if(u.id!==r.self_id){const actions=document.createElement('div');actions.className='member-actions';const challenge=document.createElement('button');challenge.className='text-action';challenge.textContent='Desafiar ↗';challenge.onclick=()=>challengePlayer(u.id,u.name,false);actions.append(challenge);if(r.self_id===r.host_id){const kick=document.createElement('button');kick.className='text-action';kick.textContent='Expulsar';kick.onclick=()=>confirmAction('Expulsar a '+u.name+' de la sala',()=>api('kick',{target:u.id}));actions.append(kick);}el.append(actions);}$('#members').append(el);}if(r.users.length>pageSize){const bar=document.createElement('div');bar.className='member-pagination';for(const [title,delta] of [['←',-1],['→',1]]){const b=document.createElement('button');b.textContent=title;b.disabled=delta<0?memberPage===0:(memberPage+1)*pageSize>=r.users.length;b.onclick=()=>{memberPage+=delta;renderLobby();};bar.append(b);}$('#members').append(bar);}}
if(changed('chat',[r.room_code,r.messages])){const stream=$('#lobby-chat'),follow=stream.scrollHeight-stream.scrollTop-stream.clientHeight<60;stream.replaceChildren();for(const m of r.messages)chatMessage(stream,m.author,m.text,m.author===me?.name?'mine':'');if(follow)stream.scrollTop=stream.scrollHeight;}
const d=r.duel;const box=$('#incoming-duel');if(changed('duel',[d,r.combat?.status])){box.replaceChildren();box.hidden=!d;if(d){box.innerHTML=`<span class="eyebrow">${d.status==='pending'?'DESAFÍO PENDIENTE':r.combat?.status==='finished'?'DUELO FINALIZADO':'DUELO EN CURSO'}</span><h3 style="margin-top:8px">${esc(d.name1)} vs ${esc(d.name2)}</h3><p>FT${d.ft} · ${d.seconds} segundos · máximo ${d.characters} personajes</p>`;for(const [text,op] of d.status==='pending'&&d.to===r.self_id?[['ACEPTAR','accept_duel'],['Rechazar','decline_duel']]:[]){const b=document.createElement('button');b.className='primary';b.textContent=text;b.onclick=()=>api(op);box.append(b);}const view=document.createElement('button');view.className='text-action';view.textContent='Ver estado ↗';view.onclick=()=>showView('duel');box.append(view);if((d.status==='pending'||r.combat?.status==='running')&&(r.self_id===r.host_id||[d.from,d.to].includes(r.self_id))){const cancel=document.createElement('button');cancel.className='text-action';cancel.textContent='Cancelar duelo';cancel.onclick=()=>confirmAction('Cancelar este duelo',()=>api('cancel_duel'));box.append(cancel);}}}}
function challengePlayer(target,name,friend){dialog(`<span class="eyebrow">DUELO DIRECTO</span><h2 style="margin-top:12px">Acuerden las reglas.</h2><p>Desafío a ${esc(name)}. El rival debe aceptar.</p><form id="duel-rules"><div class="rule-inputs"><label>Primero a<select name="ft">${[1,2,3,4,5].map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></label><label>Segundos<select name="seconds"><option>180</option><option>240</option><option>360</option><option>480</option></select></label><label>Máximo de personajes<select name="characters"><option>1</option><option selected>2</option><option>3</option><option>4</option><option>5</option></select></label></div><p>Los personajes se seleccionan dentro del juego.</p>${footer('ENVIAR DESAFÍO')}</form>`);$('#duel-rules').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await api('challenge',{target,friend,ft:Number(f.get('ft')),seconds:Number(f.get('seconds')),characters:Number(f.get('characters'))})){closeDialog();toast('Desafío enviado; esperando respuesta.');}};}
screen('duel',`<div class="view-heading duel-heading"><div><button class="back" id="duel-back" onclick="showView(state?.room?'lobby':'rooms')">← Volver</button><span class="eyebrow">BTC / DUELOS</span><h1 id="duel-heading">Frente a frente.</h1></div><div class="duel-phase-badge" id="duel-phase"></div></div><div class="duel-arena"><div class="duel-players" id="match-preview"></div><div class="duel-rules" id="match-rules"></div><div class="duel-status" id="duel-status" aria-live="polite"></div><div class="prototype-actions" id="duel-actions"></div><button class="text-action duel-history" onclick="history()">Mi historial de combates ↗</button></div>`);
function renderCombat(){
    const v=state?.duel_view;if(!v)return;
    const done=v.phase==='finished',ft=v.ft||0;
    $('#duel-heading').textContent=done?(v.winner_name?'GG. Set terminado.':'Set terminado.'):'Frente a frente.';
    const phaseLabels={idle:'SIN DUELO',pending:'DESAFÍO PENDIENTE',launching:'ABRIENDO JUEGO',connecting:'CONECTANDO',active:'EN JUEGO',confirming:'CONFIRMANDO',finished:'RESULTADO CONFIRMADO'};
    $('#duel-phase').textContent=phaseLabels[v.phase]||'';$('#duel-phase').dataset.phase=v.phase;
    const player=(p,i)=>{
        const dots=Array.from({length:ft},(_,n)=>`<i class="${n<p.wins?'won':''}"></i>`).join('');
        const portrait=p.is_self&&state.avatar?`<img src="${esc(state.avatar)}" alt="">`:esc(Array.from(p.name)[0]||'?');
        return `<article class="duel-player player-${i+1} ${p.winner?'set-winner':''}"><div class="duel-player-top"><span class="duel-player-side">P${i+1}${p.is_self?' · TÚ':''}</span>${p.winner?'<span class="duel-victory">VICTORIA</span>':''}</div><span class="duel-avatar">${portrait}</span><h2 title="${esc(p.name)}">${esc(p.name)}</h2><span class="duel-wins">${p.wins}${ft?' / '+ft:''} <small>victorias del set</small></span><div class="duel-pips" aria-label="${p.wins} victorias de ${ft}">${dots}</div><p class="duel-remaining">${done?(p.winner?'Ganador del set':'Set finalizado'):ft?(p.remaining===1?'A una victoria del set':`Faltan ${p.remaining} para ganar`):'Esperando las reglas'}</p></article>`;
    };
    const target=ft?'FT'+ft:'VS';
    const count=`<div class="duel-center"><span class="duel-target">${target}</span><div class="duel-count"><strong>${v.score[0]}</strong><span>:</span><strong>${v.score[1]}</strong></div><span class="duel-target-note">${ft?'PRIMERO A '+ft:'DUELO BTC'}</span></div>`;
    $('#match-preview').innerHTML=player(v.players[0],0)+count+player(v.players[1],1);
    $('#match-rules').innerHTML=v.ft?`<span><strong>${v.ft}</strong> victorias para ganar</span><span><strong>${v.seconds}</strong> segundos</span><span>Máximo <strong>${v.characters}</strong> personajes</span>`:'Los personajes se eligen dentro del juego.';
    $('#duel-status').textContent=state.rematch_pending?'Preparando revancha. El rival deberá aceptar.':v.status;
    const actions=$('#duel-actions');actions.replaceChildren();
    const button=(text,style,action,disabled=false)=>{const b=document.createElement('button');b.textContent=text;b.className=style;b.onclick=action;b.disabled=disabled;actions.append(b);};
    if(done){
        button(state.rematch_pending?'PREPARANDO REVANCHA…':'REVANCHA ↗','primary',()=>api('rematch',{battle_id:v.id}),state.rematch_pending||state.busy||!v.can_rematch);
        button(v.temporary?'SALIR':'VOLVER A LA SALA','secondary',async()=>{if(await api('duel_done'))showView(state.room&&!v.temporary?'lobby':'home');});
    }else if(v.can_accept){
        button('ACEPTAR DUELO ↗','primary',()=>api('accept_duel'),state.busy);
        button('Rechazar','secondary',()=>api('decline_duel'),state.busy);
    }else if(v.phase==='idle')button('BUSCAR RIVAL ↗','primary',()=>showView('rooms'));
    else if(!state.running&&v.id)button('Abrir juego','secondary',launch,state.busy);
}
const dm=document.createElement('aside');dm.className='dm-window';dm.hidden=true;dm.innerHTML='<div class="dm-header"><span><strong id="dm-name"></strong><small>Conversación privada</small></span><button onclick="closeDm()" aria-label="Cerrar chat">×</button></div><div class="chat-stream" id="dm-stream"></div><form class="chat-compose" id="dm-compose"><input maxlength="500" placeholder="Escribe un mensaje…" required><button>ENVIAR ↗</button></form>';$('.workspace').append(dm);
async function openDm(friend){$('#context').hidden=true;messageNotice.hidden=true;dmPeer=friend.id;$('#dm-name').textContent=friend.name;dm.hidden=false;$('#dm-stream').replaceChildren();await api('social',{op:'messages',target:friend.id});}
function closeDm(){dm.hidden=true;dmPeer='';api('close_chat');}
$('#dm-compose').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input');if(await api('social',{op:'message',target:dmPeer,text:input.value}))input.value='';};
function friendContext(e,f){e.preventDefault();const menu=$('#context');menu.replaceChildren();for(const [title,fn] of [['Enviar mensaje',()=>openDm(f)],['Invitar a mi sala',()=>api('social',{op:'invite',target:f.id})],['Desafiar a un duelo',()=>challengePlayer(f.id,f.name,true)],['Eliminar amigo',()=>confirmAction('Eliminar a '+f.name+' de tus amigos',()=>api('social',{op:'remove_friend',target:f.id}))]]){const b=document.createElement('button');b.textContent=title;b.onclick=()=>{menu.hidden=true;fn();};menu.append(b);}menu.hidden=false;menu.style.left=Math.max(8,Math.min(e.clientX,innerWidth-205))+'px';menu.style.top=Math.max(8,Math.min(e.clientY,innerHeight-195))+'px';}
let socialNoticePage=0,socialNoticeTimer;
const seenSocialMessages=new Set(),seenSocialActions=new Set();
const socialNotices=document.createElement('section');socialNotices.id='social-notices';
$('#social').insertBefore(socialNotices,$('.social-hint'));
const messageNotice=document.createElement('button');messageNotice.id='social-message-notice';messageNotice.hidden=true;messageNotice.setAttribute('aria-live','polite');document.body.append(messageNotice);
function renderSocialNotices(signals){
    const list=signals.actions;socialNotices.replaceChildren();socialNotices.hidden=!list.length;
    if(!list.length)return;
    socialNoticePage=Math.min(socialNoticePage,list.length-1);
    const item=list[socialNoticePage];
    const heading=document.createElement('div');heading.className='section-line';heading.innerHTML='<span>SOLICITUDES / '+list.length+'</span>';
    if(list.length>1){const pager=document.createElement('span');for(const [label,delta] of [['←',-1],['→',1]]){const b=document.createElement('button');b.textContent=label;b.disabled=delta<0?socialNoticePage===0:socialNoticePage===list.length-1;b.onclick=()=>{socialNoticePage+=delta;renderFriends();};pager.append(b);}heading.append(pager);}
    socialNotices.append(heading);
    const title=document.createElement('strong');title.textContent=item.name;socialNotices.append(title);
    const line=document.createElement('p');line.textContent=item.actionKind==='friend'?'Quiere agregarte como amigo.':'Te invita a '+(item.title||'su sala')+'.';socialNotices.append(line);
    const actions=document.createElement('div');actions.className='social-request-actions';
    for(const [label,accept] of [['Aceptar',true],['Rechazar',false]]){const b=document.createElement('button');b.className=accept?'primary':'secondary';b.textContent=label;b.onclick=async()=>{actions.querySelectorAll('button').forEach(x=>x.disabled=true);const args=item.actionKind==='friend'?{op:accept?'accept_friend':'reject_friend',target:item.id}:{op:accept?'accept':'decline',event:item.id};const result=await api('social',args);if(result)toast('Respuesta enviada.');setTimeout(()=>actions.querySelectorAll('button').forEach(x=>x.disabled=false),1500);};actions.append(b);}
    socialNotices.append(actions);
}
function renderFriends(){
    const rows=state.social?.friends||[],signals=socialSignals(state.social);
    $('#friends-count').textContent='AMIGOS / '+rows.length;
    const size=innerHeight<760?(signals.actions.length?2:5):(signals.actions.length?5:8);
    friendPage=Math.min(friendPage,Math.max(0,Math.ceil(rows.length/size)-1));friends.replaceChildren();
    for(const f of [...rows].sort((a,b)=>Number(!!signals.unread[b.id])-Number(!!signals.unread[a.id])||Number(b.online)-Number(a.online)||a.name.localeCompare(b.name)).slice(friendPage*size,(friendPage+1)*size)){
        const count=signals.unread[f.id]||0,el=document.createElement('button');el.className='friend'+(count?' has-unread':'');el.dataset.friend=f.id;
        el.setAttribute('aria-label',f.name+(count?', '+count+' mensajes nuevos':', abrir conversación'));
        el.innerHTML=`<span class="avatar">${esc(f.name[0])}</span><span class="friend-copy"><strong><span class="friend-display-name">${esc(f.name)}</span>${count?'<span class="friend-unread">'+count+'</span>':''}</strong><small class="${count?'unread-label':f.online?'live':''}">${count?'Mensaje nuevo · abrir chat':esc({playing:'En el juego',room:'En una sala',online:'Disponible',offline:'Desconectado'}[f.activity]||(f.online?'Disponible':'Desconectado'))}</small></span>`;
        el.onclick=()=>openDm(f);el.oncontextmenu=e=>friendContext(e,f);friends.append(el);
    }
    if(!rows.length)friends.innerHTML='<p class="social-hint">Agrega amigos usando su código BTC.</p>';
    if(rows.length>size){const bar=document.createElement('div');for(const [title,d] of [['←',-1],['→',1]]){const b=document.createElement('button');b.textContent=title;b.disabled=d<0?friendPage===0:(friendPage+1)*size>=rows.length;b.onclick=()=>{friendPage+=d;renderFriends();};bar.append(b);}friends.append(bar);}
    $('#inbox-summary').textContent=signals.total?signals.total+' avisos pendientes':'Sin avisos pendientes';
    $('#social-toggle .notification').hidden=!signals.total;
    $('#social-toggle').setAttribute('aria-label',signals.total?'Amigos · '+signals.total+' avisos pendientes':'Mostrar u ocultar amigos');
    $('#friend-code').textContent=state.social?.me?.code?'Copiar '+state.social.me.code:'Mi código de amigo';
    renderSocialNotices(signals);
    const freshAction=signals.actions.find(a=>!seenSocialActions.has(a.actionKind+':'+a.id));
    for(const a of signals.actions)seenSocialActions.add(a.actionKind+':'+a.id);
    if(freshAction){openFriends();toast(freshAction.name+(freshAction.actionKind==='friend'?' te envió una solicitud de amistad.':' te invitó a su sala.'));}
    const fresh=newSocialSignals(state.social?.events,seenSocialMessages).filter(e=>dm.hidden||e.sender!==dmPeer);
    if(fresh.length){const event=fresh[0];clearTimeout(socialNoticeTimer);messageNotice.textContent=event.name+' te envió un mensaje · Abrir chat ↗';messageNotice.hidden=false;messageNotice.onclick=()=>{messageNotice.hidden=true;openDm({id:event.sender,name:event.name});};socialNoticeTimer=setTimeout(()=>messageNotice.hidden=true,7000);}
}

function inviteFromList(){if(!state?.room){toast('Entra primero en una sala.');return;}const rows=(state.social?.friends||[]).filter(f=>f.online);dialog('<h2>Invita a tu sala.</h2><p>Amigos conectados</p><div id="invite-list"></div><footer><button class="secondary" onclick="closeDialog()">Cerrar</button></footer>');for(const f of rows){const b=document.createElement('button');b.className='friend';b.textContent=f.name;b.onclick=async()=>{if(await api('social',{op:'invite',target:f.id})){closeDialog();toast('Invitación enviada.');}};$('#invite-list').append(b);}if(!rows.length)$('#invite-list').textContent='No hay amigos disponibles.';}
