function renderNews(){if(!$('#news-notes'))return;const rows=newsRows();if(changed('news',rows)){const select=$('#news-version');select.replaceChildren();rows.forEach((r,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent=r.name;select.append(opt);});newsVersion=Math.min(newsVersion,rows.length-1);select.value=newsVersion;select.onchange=e=>{newsVersion=Number(e.target.value);newsPage=0;renderNews();};}const pages=notePages(rows[newsVersion]?.notes);newsPage=Math.min(newsPage,pages.length-1);$('#news-notes').textContent=pages[newsPage];$('#news-count').textContent=(newsPage+1)+' / '+pages.length;$('#news-status').textContent=state.checking?'Consultando GitHub…':state.release_error?'No se pudo consultar GitHub. Puedes reintentar y seguir jugando.':({available:'Hay una actualización del Loader disponible.',current:'Estás al día.',missing_asset:'La publicación aún no incluye el paquete del Loader.'}[state.update_state]||'Consulta las notas de esta versión.');$('#install-update').disabled=state.busy||state.running||state.checking||state.update_state!=='available';}
