window.btcReady=true;

let rankedPage=0;
screen('ranked',`<span class="eyebrow">BETA COMPETITIVA / BTC</span><div class="view-heading"><div><h1>Cada set cuenta.</h1><p>FT2 · 360 segundos · máximo 2 personajes. Selección dentro del juego.</p></div><button class="secondary" onclick="api('ranked_refresh')">Actualizar</button></div><div class="ranked-layout"><div class="ranked-overview"><span class="eyebrow" id="rank-tier">CLASIFICACIÓN PROVISIONAL</span><div class="ranked-points" id="rank-points">—</div><p class="muted" id="rank-record">Conectando tu perfil BTC…</p><div class="ranked-state" id="rank-state">Preparando la beta.</div><div id="rank-match" class="ranked-match" hidden></div><div class="ranked-actions"><button class="primary" id="rank-queue" onclick="api('ranked_queue')">BUSCAR RANKED ↗</button><button class="secondary" id="rank-cancel" onclick="api('ranked_cancel')" hidden>Cancelar búsqueda</button><button class="secondary" id="rank-forfeit" onclick="rankedForfeit()" hidden>Abandonar set</button></div><p class="ranked-hint">Salir voluntariamente o cerrar el juego durante el set cuenta como derrota. Una desconexión de un solo jugador tiene 45 segundos de margen. Los casos ambiguos no otorgan puntos.</p><button class="text-action" onclick="rankedHistory()">Ver historial ranked ↗</button></div><div class="ranked-ladder"><div class="section-line"><span>CLASIFICACIÓN DE LA BETA</span><span id="rank-season">BTC / PRUEBAS</span></div><div id="rank-leaderboard"></div><div class="rank-pagination"><button class="text-action" onclick="rankedPage=Math.max(0,rankedPage-1);renderRanked()">←</button><span id="rank-page-count"></span><button class="text-action" onclick="rankedPage++;renderRanked()">→</button></div><p class="ranked-hint">Puntuación provisional del perfil BTC de este PC. Esta temporada de prueba podrá reiniciarse antes de la clasificación oficial.</p></div></div>`);
