function rankedHistory(){const rows=state?.ranked?.history||[];dialog('<h2>Tus sets ranked.</h2><p>Resultados guardados por el servidor de la beta.</p><div id="rank-history" style="max-height:48vh;overflow:auto"></div><footer><button class="secondary" onclick="closeDialog()">Cerrar</button></footer>');if(!rows.length)$('#rank-history').innerHTML='<p>Aún no hay sets terminados.</p>';for(const r of rows){const row=document.createElement('div');row.className='notification-item';row.innerHTML='<h3>'+r.names.map(esc).join(' vs ')+'</h3><p>'+esc(r.reason)+' · '+(r.delta>0?'+':'')+r.delta+' puntos · '+esc(new Date(r.finished).toLocaleDateString())+'</p>';$('#rank-history').append(row);}}
function renderRanked(){if(!state)return;const r=state.ranked,match=r?.match,active=!!match&&!match.finished,queued=!!r?.queued,blocked=!!r&&Date.now()<r.me.blocked_until;
$('#rank-points').textContent=r?r.me.rating:'—';$('#rank-tier').textContent=r?r.me.tier+' / RANKED BETA':'CLASIFICACIÓN PROVISIONAL';$('#rank-record').textContent=r?r.me.wins+' victorias · '+r.me.losses+' derrotas · '+r.me.played+' sets':state.ranked_status;
$('#rank-state').textContent=state.busy?state.status:state.ranked_error?state.ranked_error:queued?'Buscando un rival compatible…':active?(match.phase==='playing'?'Set en curso · continúa en el juego.':'Rival encontrado. Preparando la selección de personajes…'):blocked?'Espera '+Math.ceil((r.me.blocked_until-Date.now())/1000)+' s por el abandono anterior.':r?(state.ranked_rules_ready?state.ranked_status:'El formato FT2 / 360 s / 2 personajes está pendiente de activación en el servicio.'):state.ranked_status;
$('#rank-queue').hidden=active||queued;$('#rank-queue').disabled=state.busy||!!state.room||!state.social||!r||blocked||!state.ranked_rules_ready;$('#rank-cancel').hidden=!queued;$('#rank-forfeit').hidden=!active;
const box=$('#rank-match');box.hidden=!match||queued;if(match){const result=match.finished?(match.winner===null?'SET SIN PUNTOS':match.winner===r.me.id?'GG · VICTORIA':'GG · DERROTA'):'TU PRÓXIMO SET';box.innerHTML='<span class="eyebrow">'+result+'</span><h3>'+match.names.map(esc).join(' <span class="muted">vs</span> ')+'</h3>'+(match.finished?'<p>'+esc(match.reason)+' · <strong>'+(match.delta>0?'+':'')+match.delta+' puntos</strong></p>':'<p>FT2 · 360 s · 2 personajes</p>');}
const rows=r?.leaderboard||[],size=innerHeight<760?4:6;rankedPage=Math.min(rankedPage,Math.max(0,Math.ceil(rows.length/size)-1));$('#rank-page-count').textContent=(rankedPage+1)+' / '+Math.max(1,Math.ceil(rows.length/size));$('#rank-season').textContent=r?.season||'BTC / PRUEBAS';if(changed('ladder',[rows,rankedPage,size])){const list=$('#rank-leaderboard');list.replaceChildren();for(const [offset,p] of rows.slice(rankedPage*size,(rankedPage+1)*size).entries()){const el=document.createElement('div');el.className='rank-entry';el.innerHTML='<span class="muted">'+(rankedPage*size+offset+1).toString().padStart(2,'0')+'</span><span>'+esc(p.name)+'<small>'+esc(p.tier)+' · '+p.played+' sets</small></span><strong>'+p.rating+'</strong>';list.append(el);}if(!rows.length)list.innerHTML='<p class="room-empty">La clasificación aparecerá al conectar el servicio ranked.</p>';}}

// First installation uses only the bundled, reviewed engine and the user's files.
function setupDialog(){
    dialog(`<span class="eyebrow">PRIMERA INSTALACIÓN</span><h2>Prepara tu BTC.</h2><p>Motor 0.1.38.1 incluido. Selecciona tus archivos; no se descarga el decomp.</p><div class="setup-files">${[['destination','Carpeta de instalación','Elegir carpeta'],['iso','ISO competitiva','Elegir ISO'],['memory','Memory PS2 · opcional para offline','Elegir memory']].map(([id,label,button])=>`<div class="setup-file"><div><strong>${label}</strong><span id="setup-${id}" class="setup-path"></span></div><button class="secondary setup-pick" onclick="api('setup_choose',{field:'${id}'})">${button}</button></div>`).join('')}</div><button id="setup-clear-memory" class="text-action" onclick="api('setup_clear_memory')">Continuar sin memory</button><p class="setup-note">Se creará una carpeta nueva CompetitiveRuntime. No se reemplaza ninguna instalación. La memory competitiva será necesaria para ranked y debe coincidir entre jugadores.</p><div class="setup-progress" aria-live="polite"><strong id="setup-step"></strong><p id="setup-message"></p><p id="setup-error" class="setup-error"></p></div><footer><button class="secondary" id="setup-close" onclick="closeDialog()">Cerrar</button><button class="primary" id="setup-start" onclick="api('setup_start')">INSTALAR BTC</button><button class="primary" id="setup-play" hidden onclick="closeDialog();launch()">JUGAR ↗</button></footer>`);
    $('#dialog').classList.add('setup-dialog');renderSetup();
}
function renderSetup(){
    if(!$('#setup-start')||!state?.setup)return;
    const v=state.setup,installing=v.phase==='installing',done=v.phase==='complete';
    for(const field of ['destination','iso','memory']){const el=$('#setup-'+field);el.textContent=v[field]||(field==='memory'?'Puedes importarla después desde Ajustes.':'Sin seleccionar');el.title=v[field]||'';}
    document.querySelectorAll('.setup-pick').forEach(b=>b.disabled=state.busy||state.running);
    $('#setup-clear-memory').hidden=!v.memory||done;$('#setup-clear-memory').disabled=state.busy;
    $('#setup-close').disabled=installing||state.busy;
    $('#setup-start').hidden=done;$('#setup-start').disabled=state.busy||state.running||!v.iso;
    $('#setup-play').hidden=!done;
    $('#setup-step').textContent=({engine:'1 / 6 · Motor incluido',extract:'2 / 6 · Datos competitivos',intro:'3 / 6 · Intro compatible',memory:'4 / 6 · Memory',validate:'5 / 6 · Verificación',publish:'6 / 6 · Guardando',complete:'BTC listo para jugar'})[v.step]||'Elige tus archivos para comenzar';
    $('#setup-message').textContent=v.message||'La preparación puede tardar varios minutos.';
    $('#setup-error').textContent=v.error||'';
}

function performanceDialog(){
    dialog('<span class="eyebrow">RENDIMIENTO DEL JUEGO</span><h2>Fluidez.</h2><p>Los cambios se aplican al volver a abrir el juego.</p><label><input type="checkbox" id="art-performance"> Filtro rápido de texturas de idiomas</label><p>Reduce comprobaciones de imágenes cuando se usa arte de idiomas europeos. Conserva la comprobación completa de las coincidencias.</p><label><input type="checkbox" id="timer-performance"> Temporización precisa de Windows · opcional</label><p>Alternativa de temporizador. Puede mejorar o empeorar la regularidad según el equipo; viene desactivada. Si notas más tirones, desactívala.</p><footer><button class="secondary" onclick="closeDialog()">Cerrar</button></footer>');
    $('#art-performance').checked=state?.preferences.fast_menu_art!==false;
    $('#timer-performance').checked=state?.preferences.precise_timing===true;
    $('#art-performance').onchange=e=>api('preferences',{fast_menu_art:e.target.checked});
    $('#timer-performance').onchange=e=>api('preferences',{precise_timing:e.target.checked});
}

// Diagnostics notice is visible once per client session; preference remains in the local profile.
let diagnosticNoticeShown=false;

function diagnosticsDialog(){
 dialog('<span class="eyebrow">SOPORTE BTC</span><h2>Diagnósticos de desync.</h2><label><input type="checkbox" id="diagnostics-setting"> Enviar automáticamente</label><p>Activado por defecto. Cuando el motor confirma un desync, envía al equipo BTC las versiones, huellas de datos, reglas, jugadores y estado técnico de red.</p><p>No envía chats, ISO, memory, credenciales ni rutas personales. Retención del servicio: 14 días. Los envíos pendientes se eliminan al desactivarlo.</p><p id="diagnostics-status"></p><button class="text-action" id="diagnostics-history">Enviar diagnósticos anteriores ↗</button><footer><button class="secondary" onclick="showSettings()">Volver a Ajustes</button><button class="primary" onclick="closeDialog()">Listo</button></footer>');
 $('#diagnostics-history').onclick=()=>confirmAction('Enviar resúmenes técnicos de los registros anteriores a BTC. Sin archivos completos ni chats.',()=>api('diagnostics_history'));
 $('#diagnostics-setting').checked=state?.diagnostics?.enabled!==false;
 $('#diagnostics-status').textContent=state?.diagnostics?.status||'';
 $('#diagnostics-setting').onchange=async e=>{await api('diagnostics',{enabled:e.target.checked});$('#diagnostics-status').textContent=e.target.checked?'Envío automático activado':'Desactivado · cola pendiente eliminada';};
}
